//! The page objects file as data: modules of constants, read from and written to text.
//!
//! The file is Rust, but only the shape that `sbrs extract-objects` writes is read back:
//!
//! ```text
//! // PAGE OBJECTS FILE >>> (autogenerated by `sbrs extract-objects`)
//! #![allow(dead_code)]
//!
//! /// https://example.com/login
//! pub mod example_com_login {
//!     pub const USER: &str = "#user";
//! }
//! ```
//!
//! Blank lines, `//` comments and inner attributes are read over; anything else is refused, so a
//! hand-written file is never rewritten into something else.

use super::lexer::{lex, Kind};
use super::scan::literal_value;

/// The module of the selectors found before any page was opened.
pub(super) const DEFAULT_MODULE: &str = "page";

/// How many words of a URL or a selector go into a name.
const MAX_WORDS: usize = 6;

/// The first lines of the page objects file.
const HEADER: &str =
    "// PAGE OBJECTS FILE >>> (autogenerated by `sbrs extract-objects`)\n#![allow(dead_code)]\n";

/// Words that cannot be the name of a module.
const KEYWORDS: &[&str] = &[
    "abstract", "as", "async", "await", "become", "box", "break", "const", "continue", "crate",
    "do", "dyn", "else", "enum", "extern", "false", "final", "fn", "for", "gen", "if", "impl",
    "in", "let", "loop", "macro", "match", "mod", "move", "mut", "override", "priv", "pub", "ref",
    "return", "self", "static", "struct", "super", "trait", "true", "try", "type", "typeof",
    "unsafe", "unsized", "use", "virtual", "where", "while", "yield",
];

/// One page object: a constant that holds a selector.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) struct Constant {
    /// The name of the constant.
    pub(super) name: String,
    /// The selector as a Rust string literal, written as it was in the test.
    pub(super) literal: String,
}

/// The page objects of one page.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) struct Module {
    name: String,
    url: Option<String>,
    constants: Vec<Constant>,
}

/// The whole page objects file.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub(super) struct PageObjects {
    modules: Vec<Module>,
}

impl PageObjects {
    /// Reads the text of a page objects file.
    pub(super) fn parse(text: &str) -> Result<Self, String> {
        let mut objects = Self::default();
        let mut url: Option<String> = None;
        let mut open: Option<usize> = None;
        for (number, raw) in text.lines().enumerate() {
            let line = raw.trim();
            let unreadable = || {
                format!(
                    "line {} is not one that `sbrs extract-objects` writes: {line}",
                    number + 1
                )
            };
            if line.is_empty() {
                continue;
            }
            let Some(index) = open else {
                if let Some(doc) = line.strip_prefix("///") {
                    url = Some(doc.trim().to_owned());
                    continue;
                }
                if line.starts_with("//") || (line.starts_with("#![") && line.ends_with(']')) {
                    continue;
                }
                let name = line
                    .strip_prefix("pub mod ")
                    .or_else(|| line.strip_prefix("mod "))
                    .and_then(|rest| rest.strip_suffix('{'))
                    .map(str::trim)
                    .filter(|name| is_identifier(name))
                    .ok_or_else(unreadable)?;
                let existing = objects
                    .modules
                    .iter()
                    .position(|module| module.name == name);
                let index = existing.unwrap_or_else(|| {
                    objects.modules.push(Module {
                        name: name.to_owned(),
                        url: url.take().filter(|url| !url.is_empty()),
                        constants: Vec::new(),
                    });
                    objects.modules.len() - 1
                });
                url = None;
                open = Some(index);
                continue;
            };
            if line == "}" {
                open = None;
            } else if !line.starts_with("//") {
                let constant = parse_constant(line).ok_or_else(unreadable)?;
                objects.modules[index].constants.push(constant);
            }
        }
        if open.is_some() {
            return Err("a module is not closed".to_owned());
        }
        Ok(objects)
    }

    /// The text of the file.
    pub(super) fn render(&self) -> String {
        let mut text = String::from(HEADER);
        for module in &self.modules {
            text.push('\n');
            if let Some(url) = &module.url {
                text.push_str("/// ");
                text.push_str(url);
                text.push('\n');
            }
            text.push_str("pub mod ");
            text.push_str(&module.name);
            text.push_str(" {\n");
            for constant in &module.constants {
                text.push_str("    pub const ");
                text.push_str(&constant.name);
                text.push_str(": &str = ");
                text.push_str(&constant.literal);
                text.push_str(";\n");
            }
            text.push_str("}\n");
        }
        text
    }

    /// Adds the selector `literal` of the page loaded from `url`, unless the page has it.
    /// Returns whether it was new.
    pub(super) fn add(&mut self, url: Option<&str>, literal: &str) -> bool {
        let url = url.filter(|url| !url.is_empty());
        let name = module_name(url);
        let index = match self.modules.iter().position(|module| module.name == name) {
            Some(index) => index,
            None => {
                self.modules.push(Module {
                    name,
                    url: url.map(str::to_owned),
                    constants: Vec::new(),
                });
                self.modules.len() - 1
            }
        };
        let module = &mut self.modules[index];
        if module
            .constants
            .iter()
            .any(|constant| constant.literal == literal)
        {
            return false;
        }
        let name = constant_name(literal, &module.constants);
        module.constants.push(Constant {
            name,
            literal: literal.to_owned(),
        });
        true
    }

    /// The constant of `module` that holds `literal`.
    pub(super) fn constant(&self, module: &str, literal: &str) -> Option<&Constant> {
        self.modules
            .iter()
            .find(|candidate| candidate.name == module)?
            .constants
            .iter()
            .find(|constant| constant.literal == literal)
    }

    /// The literal that the constant `name` of `module` holds.
    pub(super) fn literal(&self, module: &str, name: &str) -> Option<&str> {
        self.modules
            .iter()
            .find(|candidate| candidate.name == module)?
            .constants
            .iter()
            .find(|constant| constant.name == name)
            .map(|constant| constant.literal.as_str())
    }
}

/// Reads `pub const NAME: &str = "literal";`.
fn parse_constant(line: &str) -> Option<Constant> {
    let rest = line.strip_prefix("pub const ")?;
    let (name, rest) = rest.split_once(':')?;
    let name = name.trim();
    let rest = rest
        .trim_start()
        .strip_prefix("&str")?
        .trim_start()
        .strip_prefix('=')?;
    let literal = rest.trim().strip_suffix(';')?.trim();
    if !is_identifier(name) || !is_string_literal(literal) {
        return None;
    }
    Some(Constant {
        name: name.to_owned(),
        literal: literal.to_owned(),
    })
}

/// Whether `text` is one string literal and nothing else.
fn is_string_literal(text: &str) -> bool {
    matches!(
        lex(text).tokens.as_slice(),
        [token] if token.kind == Kind::Str && token.start == 0 && token.end == text.len()
    )
}

/// Whether `name` is a plain ASCII identifier.
fn is_identifier(name: &str) -> bool {
    let mut chars = name.chars();
    chars
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_')
        && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

/// The lowercase words of `text`: its runs of ASCII letters and digits.
fn words(text: &str) -> Vec<String> {
    text.split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|word| !word.is_empty())
        .map(str::to_ascii_lowercase)
        .collect()
}

/// The name of the module for the page loaded from `url`: the words of the URL without its
/// scheme, a leading `www.`, query and fragment. `page` when there is no URL or no word in it.
pub(super) fn module_name(url: Option<&str>) -> String {
    let Some(url) = url.filter(|url| !url.is_empty()) else {
        return DEFAULT_MODULE.to_owned();
    };
    let rest = match url.split_once("://") {
        Some((scheme, rest))
            if scheme
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || "+.-".contains(c)) =>
        {
            rest
        }
        _ => url,
    };
    let rest = rest.strip_prefix("www.").unwrap_or(rest);
    let rest = rest.split(['?', '#']).next().unwrap_or(rest);
    let mut words = words(rest);
    words.truncate(MAX_WORDS);
    if words.is_empty() {
        return DEFAULT_MODULE.to_owned();
    }
    let mut name = words.join("_");
    if name.starts_with(|c: char| c.is_ascii_digit()) {
        name.insert_str(0, "page_");
    }
    if KEYWORDS.contains(&name.as_str()) {
        name.push_str("_page");
    }
    name
}

/// The name for a constant that holds `literal` in a module that already has `taken`: the first
/// words of the selector in capitals, `_2`, `_3`, ... when that name is taken, and `CSS_1`,
/// `CSS_2`, ... for a selector with no word.
fn constant_name(literal: &str, taken: &[Constant]) -> String {
    let is_taken = |name: &str| taken.iter().any(|constant| constant.name == name);
    let words = words(literal_value(literal));
    if words.is_empty() {
        let mut number = 1;
        loop {
            let name = format!("CSS_{number}");
            if !is_taken(&name) {
                return name;
            }
            number += 1;
        }
    }
    let mut base = words
        .iter()
        .take(MAX_WORDS)
        .map(|word| word.to_ascii_uppercase())
        .collect::<Vec<_>>()
        .join("_");
    if base.starts_with(|c: char| c.is_ascii_digit()) {
        base.insert_str(0, "CSS_");
    }
    if !is_taken(&base) {
        return base;
    }
    let mut number = 2;
    loop {
        let name = format!("{base}_{number}");
        if !is_taken(&name) {
            return name;
        }
        number += 1;
    }
}
